import affectsRaw from './data/control-path-affects.v1.json'
import { ownLookupOr } from '../../support/own-lookup'

export interface EpControlPathAffectEntry {
  controlId: string
  pathId: string
  pathVariants?: readonly string[]
  cells: readonly string[]
}

interface RawAffects {
  schemaVersion: number
  sheetVersion: string
  builtAt: string
  byWebKey: Record<string, EpControlPathAffectEntry[]>
}

const AFFECTS = affectsRaw as RawAffects

export const EP_CONTROL_PATH_AFFECTS_SHEET_VERSION = AFFECTS.sheetVersion

const NO_AFFECTS: readonly EpControlPathAffectEntry[] = []

export function epControlAffectsPathByWebKey(
  webKey: string,
): readonly EpControlPathAffectEntry[] {
  // Own-key lookup: webKey is untrusted (sheet/URL/tool input), so a plain
  // `byWebKey[webKey]` would return a prototype member (constructor, toString…)
  // for those keys, which `?? []` cannot reject. See src/support/own-lookup.
  return ownLookupOr(AFFECTS.byWebKey, webKey, NO_AFFECTS)
}

/**
 * Union of pathVariants on affectsPath edges for this webKey.
 * `undefined` means unrestricted (no variants listed on any edge).
 */
export function epControlPathVariantsByWebKey(
  webKey: string,
): readonly string[] | undefined {
  const entries = epControlAffectsPathByWebKey(webKey)
  if (!entries.length) return undefined
  const variants = new Set<string>()
  let anyListed = false
  for (const entry of entries) {
    if (entry.pathVariants?.length) {
      anyListed = true
      for (const v of entry.pathVariants) variants.add(v)
    }
  }
  return anyListed ? [...variants].sort() : undefined
}
